import test from 'node:test';
import assert from 'node:assert';
import { createState, frame, BRICK_H, BRICK_W, BRICK_TOP, UP, DOWN, LEFT, RIGHT } from '../game/neon.js';

const dummyCtx = {
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('D1 - Basic Bounce: Ball should bounce off a brick', () => {
  const state = createState(1);
  // Position ball so it collides with the first brick
  // Brick 0 is at (offsetX, BRICK_TOP, BRICK_W, BRICK_H)
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 2; // Just above the brick
  state.ball.vx = 0;
  state.ball.vy = 100; // Moving down

  frame(dummyCtx, state);

  assert.strictEqual(state.ball.vy < 0, true, 'Ball should be moving UP after bouncing off the top of a brick');
});

test('D2 - Tunneling: Ball should not pass through a brick at high speed', () => {
  const state = createState(5); // Higher speed
  const brick = state.bricks[0];

  // Position ball so it would skip the brick in one frame
  // Brick H = 20. Ball speed at level 5 = 620. dt = 0.05. delta = 31.
  // If ball.y = brick.y - 5 and it moves 31, it ends up at brick.y + 26 (past the brick).
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 5; 
  state.ball.vy = 620; 

  // We simulate the movement that would happen in step(), then the collision in frame()
  // But actually, the current game loop is: step(dt) then frame().
  // Let's simulate one full loop.

  // This is tricky because step() is called before frame().
  // In the actual game: 
  // 1. step(state, dt) -> updates ball.x, ball.y
  // 2. frame(ctx, state) -> checks collision and bounces

  // To test tunneling, we need to see if frame() can detect a collision 
  // when the ball has already passed through.
  // Current implementation of collides() only checks current position.

  // If we use the current implementation:
  // ball.y starts at 43. 
  // step(0.05) -> ball.y becomes 43 + 620 * 0.05 = 74.
  // brick.y is 48, brick.h is 20 -> brick bottom is 68.
  // Now ball.y is 74. collides(ball, brick) will be false because ball.y - ball.r (74-7) = 67 < 68?
  // Wait, ball.y is the center. ball.y - ball.r = 67. 
  // Brick bottom is 68. It might still collide if the radius is large enough.
  // Let's use a higher speed or smaller radius.

  state.ball.y = brick.y - 10; 
  state.ball.vy = 1000; // Very fast
  // After step(0.05): ball.y = (48-10) + 1000 * 0.05 = 38 + 50 = 88.
  // Brick bottom is 48 + 20 = 68.
  // Ball top is 88 - 7 = 81.
  // 81 > 68. No collision.

  // We need to test if the a a "swept" collision would have happened.
  // Since we are testing the current code, it SHOULD fail.
});

import test from 'node:test';
import assert from 'node:assert';
import { createState, frame, collides, BRICK_H, BRICK_W, BRICK_TOP } from '../game/neon.js';

const dummyCtx = {
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('D1 - Missing Bounce', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h / 2; // Ball is inside the brick
  state.ball.vy = 100; // Moving down

  frame(dummyCtx, state);

  assert.ok(state.ball.vy < 0, 'Ball should have bounced UP');
});

test('D2 - Tunneling', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Setup: ball is just above the brick, moving very fast
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 10; 
  state.ball.vy = 1000; 

  // Simulate one frame of movement (dt = 0.05)
  // In the real game: step() then frame()
  // We simulate the result of step() here
  state.ball.y += state.ball.vy * 0.05; // y becomes 38 + 50 = 88

  frame(dummyCtx, state);

  // If tunneling is fixed, the ball should have been detected as hitting the brick
  // and thus the brick should be dead.
  assert.strictEqual(brick.alive, false, 'Brick should be destroyed even if ball tunneled through');
});

test('D3 - Ghost Collision (Seam)', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[1];

  // Position ball exactly on the seam between two bricks
  state.ball.x = brick1.x + brick1.w; 
  state.ball.y = brick1.y + brick1.h / 2;
  state.ball.vy = 100;

  frame(dummyCtx, state);

  // If we naively flip vy for each collision, and it hits 2 bricks, 
  // vy will be flipped twice and remain 100.
  assert.ok(state.ball.vy < 0, 'Ball should only bounce once per frame per axis');
});

test('D4 - Corner Hit', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Position ball to hit the top-left corner
  state.ball.x = brick.x - 2;
  state.ball.y = brick.y - 2;
  state.ball.vx = 10;
  state.ball.vy = 10;

  // Move slightly into the corner
  state.ball.x += 4;
  state.ball.y += 4;

  frame(dummyCtx, state);

  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'Ball should bounce on both axes when hitting a corner');
});

# To Fix: Ball Collisions

Symptôme : « la balle traverse les briques au lieu de rebondir »

## D1 — Absence de rebond
- **Famille** : Collant / Basique
- **Symptôme joueur** : La balle traverse la brique, la détruit, mais continue sa trajectoire sans changer de direction.
- **Cause** : `game/neon.js:186` — La fonction `frame()` détecte la collision et détruit la brique, mais ne modifie ni la vitesse ni la position de la balle.
- **Invariant violé** : Toute collision avec un obstacle doit entraîner un changement de trajectoire (rebond).
- **Déclencheur** : Tout impact avec une brique.
- **Attendu** : La composante de vitesse perpendiculaire à la face touchée doit être inversée.
- **Référence** : [LearnOpenGL - Collision resolution](https://learnopengl.com/In-Practice/2D-Collision-resolution) — Détection de la face et inversion de la vitesse.
- **Cas test** :
  ```js
  test('D1 - Missing Bounce', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y + brick.h / 2; 
    state.ball.vy = 100;
    frame(dummyCtx, state);
    assert.ok(state.ball.vy < 0, 'Ball should have bounced UP');
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced UP`
- **Discrimine** : Une correction qui détruit la brique mais oublie de modifier `vx`/`vy`.
- **Vert quand** : Le cas D1 passe au vert.

## D2 — Traversée (Tunneling)
- **Famille** : Traversée (*tunneling*)
- **Symptôme joueur** : À haute vitesse (niveaux élevés), la balle passe à travers une brique sans la détruire ni rebondir.
- **Cause** : `game/neon.js:104` — `collides()` effectue un test discret. Si le pas de temps $\Delta y = ballSpeed \times dt$ est supérieur à la zone de collision ($BRICK\_H + 2 \times BALL\_R$), la balle peut sauter l'obstacle.
- **Invariant violé** : Aucun obstacle franchi sans rebond, quel que soit le pas.
- **Déclencheur** : $level \ge 6$ (où $ballSpeed \times 0.05 > 34$).
- **Attendu** : La collision doit être détectée même si la position finale est au-delà de l'obstacle.
- **Référence** : [Swept AABB Collision Detection](https://gamedev.net/tutorial/swept-aabb-collision-detection-and-response-r3084) — Utilisation du balayage pour détecter les intersections sur un segment.
- **Cas test** :
  ```js
  test('D2 - Tunneling', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y - 10; 
    state.ball.vy = 1000; 
    state.ball.y += state.ball.vy * 0.05; 
    frame(dummyCtx, state);
    assert.strictEqual(brick.alive, false, 'Brick should be destroyed even if ball tunneled through');
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Brick should be destroyed even if ball tunneled through`
- **Discrimine** : Une correction qui se contente d'augmenter la fréquence des tests sans changer l'algorithme en swept AABB.
- **Vert quand** : Le cas D2 passe au vert.

## D3 — Double inversion (Ghost Collision)
- **Famille** : Double inversion (*seam / ghost collision*)
- **Symptôme joueur** : La balle traverse une ligne de briques en vibrant ou en passant à travers les jointures.
- **Cause** : `game/neon.js:184` — La boucle `for (const brick of state.bricks)` peut détecter plusieurs collisions dans une même frame. Si on inverse `vy` pour chaque collision, deux collisions annulent l'effet.
- **Invariant violé** : Un rebond par passe et par axe.
- **Déclencheur** : Position de la balle sur la couture entre deux briques.
- **Attendu** : Seul le premier impact valide doit modifier la trajectoire.
- **Référence** : [Real-Time Collision Detection](https://www.amazon.com/Real-Time-Collision-Detection-Algorithm-Implementation/dp/1578645588) — Résolution des collisions multiples.
- **Cas test** :
  ```js
  test('D3 - Ghost Collision (Seam)', () => {
    const state = createState(1);
    const brick1 = state.bricks[0];
    const brick2 = state.bricks[1];
    state.ball.x = brick1.x + brick1.w; 
    state.ball.y = brick1.y + brick1.h / 2;
    state.ball.vy = 100;
    frame(dummyCtx, state);
    assert.ok(state.ball.vy < 0, 'Ball should only bounce once per frame per axis');
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should only bounce once per frame per axis`
- **Discrimine** : Une correction naïve qui fait `vy = -vy` sans vérifier si un rebond a déjà eu lieu.
- **Vert quand** : Le cas D3 passe au vert.

## D4 — Face vs Coin
- **Famille** : Face vs coin
- **Symptôme joueur** : Rebond anormal ou absence de rebond lors d'un impact sur l'angle d'une brique.
- **Cause** : `game/neon.js:186` — Absence de logique pour différencier l'axe d'impact.
- **Invariant violé** : L'axe touché est celui de la plus petite pénétration ; sur un coin, les deux axes sont inversés.
- **Déclencheur** : Impact où $|ball.x - brick.x| \approx ball.r$ et $|ball.y - brick.y| \approx ball.r$.
- **Attendu** : Inversion de `vx` et `vy` lors d'un impact de coin.
- **Référence** : [AABB Corner Resolution](https://noonat.github.io/intersect/) — Calcul de la normale de collision.
- **Cas test** :
  ```js
  test('D4 - Corner Hit', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x - 2;
    state.ball.y = brick.y - 2;
    state.ball.vx = 10;
    state.ball.vy = 10;
    state.ball.x += 4;
    state.ball.y += 4;
    frame(dummyCtx, state);
    assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'Ball should bounce on both axes when hitting a corner');
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should bounce on both axes when hitting a corner`
- **Discrimine** : Une correction qui ne gère qu'un seul axe d'impact (ex: toujours `vy`).
- **Vert quand** : Le cas D4 passe au vert.

